	title: string;
	acceptance_criteria: Array<{ id: string; description: string }>;
}

/**
 * Session budget info.
 * AC: @ui-session-stream ac-4
 */
export interface SessionBudget {
	max_per_cycle: number;
	started_this_cycle: number;
}

