   133→		total: items.length,
   134→		offset,
   135→		limit
   136→	};
   137→}
   138→
   139→/**
   140→ * Find task by reference (slug or ULID prefix)
   141→ * AC: @gh-pages-export ac-12
   142→ */
   143→function findTaskByRef(tasks: ExportedTask[], ref: string): ExportedTask | null {
   144→	const normalizedRef = ref.startsWith('@') ? ref.slice(1) : ref;
   145→
   146→	// Try exact slug match first
   147→	const bySlug = tasks.find((t) => t.slugs.includes(normalizedRef));
   148→	if (bySlug) return bySlug;
   149→
   150→	// Try ULID prefix match
   151→	const byUlid = tasks.find((t) => t._ulid.startsWith(normalizedRef.toUpperCase()));
   152→	if (byUlid) return byUlid;
   153→
   154→	return null;
   155→}
   156→
   157→/**
   158→ * Find item by reference (slug or ULID prefix)
   159→ * AC: @gh-pages-export ac-13
   160→ */
   161→function findItemByRef(items: ExportedItem[], ref: string): ExportedItem | null {
   162→	const normalizedRef = ref.startsWith('@') ? ref.slice(1) : ref;
   163→
   164→	// Try exact slug match first
   165→	const bySlug = items.find((i) => i.slugs.includes(normalizedRef));
   166→	if (bySlug) return bySlug;
   167→
   168→	// Try ULID prefix match
   169→	const byUlid = items.find((i) => i._ulid.startsWith(normalizedRef.toUpperCase()));
   170→	if (byUlid) return byUlid;
   171→
   172→	return null;
   173→}
