   176→// Static API Functions
   177→// ============================================================
   178→
   179→/**
   180→ * Fetch tasks from static snapshot
   181→ * AC: @gh-pages-export ac-11
   182→ */
   183→export function fetchTasksStatic(params?: {
   184→	status?: string;
   185→	type?: string;
   186→	tag?: string;
   187→	assignee?: string;
   188→	automation?: string;
   189→	limit?: number;
   190→	offset?: number;
   191→}): PaginatedResponse<TaskSummary> {
   192→	const snapshot = getSnapshot();
   193→	if (!snapshot) {
   194→		return { items: [], total: 0, offset: 0, limit: 50 };
   195→	}
   196→
   197→	const filtered = filterTasks(snapshot.tasks, params);
   198→	const paginated = paginate(filtered, params);
   199→
   200→	return {
   201→		...paginated,
   202→		items: paginated.items.map(toTaskSummary)
   203→	};
   204→}
