   107→		deleteConfirmOpen = true;
   108→	}
   109→
   110→	async function handleDelete() {
   111→		if (!itemToDelete) return;
   112→
   113→		// AC: @gh-pages-export ac-18 - Check static mode
   114→		if (isStaticMode()) {
   115→			error = 'Cannot delete items in read-only mode. Use the kspec CLI.';
   116→			deleteConfirmOpen = false;
   117→			itemToDelete = null;
   118→			return;
   119→		}
   120→
   121→		try {
   122→			deletingItem = true;
   123→			error = '';
   124→			await deleteInboxItem(itemToDelete._ulid);
   125→
   126→			// Remove item from list with animation
   127→			items = items.filter((i) => i._ulid !== itemToDelete!._ulid);
   128→
   129→			// Close dialog
   130→			deleteConfirmOpen = false;
   131→			itemToDelete = null;
   132→		} catch (err) {
   133→			// AC: @gh-pages-export ac-18 - Graceful error message
