    47→        (a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime()
    48→      );
    49→
    50→      return {
    51→        items: sorted,
    52→        total: sorted.length,
    53→      };
    54→    })
    55→
    56→    // AC: @api-contract ac-13 - Create inbox item
    57→    .post(
    58→      '/',
    59→      async ({ body, error: errorResponse, projectContext }) => {
    60→        // AC: @multi-directory-daemon ac-1, ac-24 - Use project context from middleware
    61→        const ctx = await initContext(projectContext.path);
    62→
    63→        // AC: @trait-api-endpoint ac-3 - Validate body
    64→        if (!body.text || typeof body.text !== 'string' || body.text.trim().length === 0) {
    65→          return errorResponse(400, {
    66→            error: 'validation_error',
    67→            details: [
    68→              {
    69→                field: 'text',
    70→                message: 'Text is required and must be a non-empty string',
    71→              },
    72→            ],
    73→          });
    74→        }
    75→
    76→        // Create inbox item input
    77→        const input: InboxItemInput = {
    78→          text: body.text,
    79→          tags: body.tags,
    80→          added_by: body.added_by,
    81→        };
    82→
    83→        // AC: @api-contract ac-13 - Generate ULID and create item
    84→        const item = createInboxItem(input, ctx.config?.identity?.author);
    85→
    86→        // Save and commit
    87→        await saveInboxItem(ctx, item);
    88→        await commitIfShadow(ctx.shadow, `inbox: add item ${item._ulid}`);
    89→
    90→        // Broadcast update
    91→        // AC: @multi-directory-daemon ac-18 - Broadcast scoped to request project
    92→        pubsub.broadcast('inbox:updates', 'inbox_item_created', {
    93→          ulid: item._ulid,
    94→        }, projectContext.path);
    95→
    96→        // AC: @api-contract ac-13 - Return item with generated ULID
    97→        return {
    98→          success: true,
    99→          item,
   100→        };
   101→      },
   102→      {
   103→        body: t.Object({
   104→          text: t.String(),
   105→          tags: t.Optional(t.Array(t.String())),
   106→          added_by: t.Optional(t.String()),
   107→        }),
   108→      }
   109→    )
   110→
   111→    // AC: @api-contract ac-14 - Delete inbox item
   112→    .delete(
   113→      '/:ref',
   114→      async ({ params, error: errorResponse, projectContext }) => {
   115→        // AC: @multi-directory-daemon ac-1, ac-24 - Use project context from middleware
   116→        const ctx = await initContext(projectContext.path);
   117→        const inboxItems = await loadInboxItems(ctx);
   118→        const tasks = await loadAllTasks(ctx);
   119→        const specItems = await loadAllItems(ctx);
   120→        const index = new ReferenceIndex(tasks, specItems);
   121→
   122→        // Resolve ref
   123→        const result = index.resolve(params.ref);
   124→        if (!result.ok) {
   125→          return errorResponse(404, {
   126→            error: 'not_found',
   127→            message: `Inbox item reference "${params.ref}" not found`,
   128→            suggestion: 'Use kspec inbox list to find valid inbox item references',
   129→          });
   130→        }
   131→
   132→        // Verify it's an inbox item
   133→        const item = findInboxItemByRef(inboxItems, result.ulid);
   134→        if (!item) {
   135→          return errorResponse(404, {
   136→            error: 'not_found',
   137→            message: `Reference "${params.ref}" is not an inbox item`,
   138→          });
   139→        }
   140→
   141→        // AC: @api-contract ac-14 - Delete item
   142→        await deleteInboxItem(ctx, result.ulid);
   143→        await commitIfShadow(ctx.shadow, `inbox: delete ${params.ref}`);
   144→
